package org.local.donusturucu.qa;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.DocumentsContract;import android.database.Cursor;import android.view.KeyEvent;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class FolderBatch extends FileList {
 Object resultOf(String name,Class<?>[]types,Object...args)throws Exception{Method m=activity.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}
 String readUri(Uri uri)throws Exception{InputStream in=getTargetContext().getContentResolver().openInputStream(uri);ByteArrayOutputStream b=new ByteArrayOutputStream();try{byte[]buf=new byte[4096];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);}finally{in.close();}return b.toString("UTF-8");}
 Uri create(Uri parent,String name,String mime,String content)throws Exception{Uri uri=DocumentsContract.createDocument(getTargetContext().getContentResolver(),parent,mime,name);if(uri==null)throw new IOException("Create failed");if(content!=null){OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri);try{out.write(content.getBytes("UTF-8"));}finally{out.close();}}return uri;}
 Set<String> children(Uri tree,Uri parent)throws Exception{Set<String>ids=new HashSet<String>();Cursor c=getTargetContext().getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(parent)),new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID},null,null,null);if(c!=null)try{while(c.moveToNext())ids.add(c.getString(0));}finally{c.close();}return ids;}
 public void onStart(){Bundle result=new Bundle();try{Intent intent=new Intent();intent.setClassName("org.local.donusturucu","org.local.donusturucu.MainActivity");intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(intent);long until=System.currentTimeMillis()+60000;while(!(Boolean)get("ready")&&System.currentTimeMillis()<until)Thread.sleep(200);require((Boolean)get("ready"));final Uri tree=(Uri)get("outputTree");if(tree==null)throw new IOException("QA output folder permission missing");Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));JSONArray rows=new JSONArray();File reportDir=new File(getTargetContext().getExternalFilesDir(null),"folder-batch-test");reportDir.mkdirs();
 for(int repeat=1;repeat<=3;repeat++)for(final boolean ku:new boolean[]{false,true}){invoke("clearFiles");ui(new Runnable(){public void run(){try{set("ku",ku);call("build",new Class<?>[]{});}catch(Exception error){throw new RuntimeException(error);}}});Uri folder=create(parent,"FolderQA-"+System.nanoTime(),DocumentsContract.Document.MIME_TYPE_DIR,null),nested=create(folder,"Alt فارسی",DocumentsContract.Document.MIME_TYPE_DIR,null);String original="1\n00:00:01,000 --> 00:00:02,000\nMerhaba فارسی\n\n",second=original.replace("Merhaba","Silav");Uri a=create(folder,"a.srt","application/x-subrip",original),b=create(nested,"a.srt","application/x-subrip",second),text=create(folder,"other.txt","text/plain","A document."),bad=create(folder,"bad.bin","application/octet-stream","\u0000bad");
 final List<Uri>input=(List<Uri>)resultOf("treeFilesFrom",new Class<?>[]{Uri.class,String.class},tree,DocumentsContract.getDocumentId(folder));require(input.size()==4);ui(new Runnable(){public void run(){try{call("importMany",new Class<?>[]{List.class,Uri.class},input,null);}catch(Exception error){throw new RuntimeException(error);}}});until=System.currentTimeMillis()+45000;while((Boolean)get("busy")&&System.currentTimeMillis()<until){Thread.sleep(100);waitForIdleSync();}require(!(Boolean)get("busy")&&((List)get("files")).size()==3&&(Boolean)get("batchEnabled"));final Set<String>before=children(tree,parent);
 ui(new Runnable(){public void run(){try{List entries=(List)get("files");for(int index=0;index<entries.size();index++){Field ext=entries.get(index).getClass().getDeclaredField("ext");ext.setAccessible(true);if("srt".equals(ext.get(entries.get(index)))){call("selectFile",new Class<?>[]{int.class},index);break;}}set("action","subtitle_text");call("buildActions",new Class<?>[]{});call("startJob",new Class<?>[]{});require((Boolean)get("busy")&&!((CheckBox)get("batchCheck")).isEnabled());}catch(Exception error){throw new RuntimeException(error);}}});until=System.currentTimeMillis()+45000;while((Boolean)get("busy")&&System.currentTimeMillis()<until){Thread.sleep(100);waitForIdleSync();}require(!(Boolean)get("busy"));Set<String>added=children(tree,parent);added.removeAll(before);require(added.size()==2);Set<String>contents=new HashSet<String>();for(String id:added){Uri uri=DocumentsContract.buildDocumentUriUsingTree(tree,id);contents.add(readUri(uri));DocumentsContract.deleteDocument(getTargetContext().getContentResolver(),uri);}require(contents.contains("Merhaba فارسی\n")&&contents.contains("Silav فارسی\n"));require(readUri(a).equals(original)&&readUri(b).equals(second)&&readUri(text).equals("A document.")&&readUri(bad).equals("\u0000bad"));sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();DocumentsContract.deleteDocument(getTargetContext().getContentResolver(),folder);JSONObject row=new JSONObject();row.put("repeat",repeat);row.put("language",ku?"ku":"tr");row.put("recursive_provider_files",4);row.put("supported_imports",3);row.put("outputs",2);row.put("bad_import_and_incompatible_operation_reported",true);row.put("originals_unchanged",true);row.put("pass",true);rows.put(row);
 JSONObject report=new JSONObject();report.put("cases",rows.length());report.put("failures",0);report.put("rows",rows);SubtitleRoundtrip.write(new File(reportDir,"report.json"),report.toString(2));}
 invoke("clearFiles");finish(0,result);
 }catch(Throwable error){result.putString("error",error.toString());if(error instanceof InvocationTargetException)result.putString("cause",((InvocationTargetException)error).getCause().toString());finish(1,result);}}
}
